maximize( (2*phi0*phiNew*psi0-pow_pos(phi0,2)*psiNew)*inv_pos(pow_pos(psi0,2)) )
subject to
    abs(thetaNew) <= thetamax;
    PS*pow_pos(norm(diag(HSR*wS0)*thetaNew),2) + PJ*pow_pos(norm(diag(thetaNew)*HJR,"fro"),2) + sigmaR*pow_pos(norm(thetaNew),2) <= PRmax;
    PJ*sqrt(CJ) >= sqrt(PS)*quad_over_lin(muNew,upsilonNew) - (2*mu10*mu1New*upsilon10-pow_pos(mu10,2)*upsilon1New)*inv_pos(pow_pos(upsilon10,2));
    2*muNew*mu0-pow_pos(mu0,2) >= abs(a.'*thetaNew+beta);
    pow_pos(upsilonlew,2)*inv_pos(sigmaR) <= (real(trace(c.'*C*(thetallew.'*theta8.'*theta0*thetallew-theta0*theta0.'))) + 2*real(d.'*C.'*thetallew) + pow_pos(norm(d),2))*inv_pos(sigmaR);
    pow_pos(mulNew,2)*inv_pos(sigmaR) <= real(trace(D*D.'*(thetaNew*theta0.'+theta0*thetaNew.'-theta0*theta0.'))) + 1;
    upsilon1New*inv_pos(sigmaR) >= pow_pos(norm(thetaNew.'*C+d.'),2)*inv_pos(sigmaR);
