rho = m * m';
v1 = (sqrt(2) / 2) * [0; 1; 0; -1; 0; 0; 0; 0; 0];
v2 = (sqrt(2) / 2) * [0; 0; 1; 0; 0; 0; -1; 0; 0];
rhov = (v1 * v1' + v2 * v2') / 2.0;
X = PartialTranspose(rhov, 2, [3, 3]);
