    variables gama(Q,1) g;
    psi = J * G1 * B;
    Y = J * y;
    VV = J * vec(eye(m));
    D = Y - VV;
minimize (g);
subject to
    G * u <= gama;
    sum(gama) <= g;        
    norm(D - psi * u) <= beta1;
cvx_end
