\mbox{s.t.} & \sum\nolimits_{k=0}^{K_{d}+1}\alpha_{k}=1 \:; \\
\mbox{\bf(}C.2) & \sum\nolimits_{i=1}^{K_{c}}\mbox{\bf Tr}\left(\mbox{\bf W}_{i }\right)\leq P_{\max} \:; \\
\mbox{\bf(}C.3) & \sum\nolimits_{l=1,l\neq i}^{K_{c}}\mbox{\bf Tr}\left(\mbox{ \bf H}_{i}\mbox{\bf W}_{l}\right)+\sigma_{z}^{2}\leq\psi_{i}^{-1}\mbox{\bf Tr }\left(\mbox{\bf H}_{i}\mbox{\bf W}_{i}\right) \:, \\
