& k=1,\ldots,K_{d} \:; \\
\mbox{\bf(}C.5)\:\&\;(C.6) & \mbox{in}\:\:(11) \:,
\end{array}
\]

where \(\tilde{R}_{k} = \log_{2}\left(1+\frac{E_{k}\left|g_{k}\right|^{2}}{\alpha_{k} \left(\sum_{l=1}^{K_{c}}P_{l}\left|g_{l,k}\right|^{2}+\sigma_{z}^{\,2}\right)}\right)\).

