        if strcmp(cvx_status, 'Solved')
            u = gamma;
            if gamma < objval_opt
                a_opt = A;
                b_opt = B;
                objval_opt = gamma;
            end
        else
            l = gamma;
        end
    end
    l = 0;
    u = max(f);
end

y_fit = Tpowers * [1; a_opt] ./ (Tpowers * [1; b_opt]);
```

